#!/usr/bin/env python3
"""
Generate a comprehensive, vetted dataset of 640 items for the "Bible or Not" game:
- 160 items in Tier 1 (Novice)
- 160 items in Tier 2 (Scholar)
- 160 items in Tier 3 (Berean)
- 160 items in Tier 4 (Master)
Each tier has exactly 80 IN_BIBLE and 80 NOT_IN_BIBLE.
"""

import json
import os

items = []
id_counter = 1

def add_item(tier, text, answer, category, explanation, reference=None, misconception=None):
    global id_counter
    item_id = f"bon-t{tier}-{id_counter:04d}"
    id_counter += 1
    item = {
        "id": item_id,
        "tier": tier,
        "text": text.strip(),
        "answer": answer,
        "category": category.strip(),
        "explanation": explanation.strip()
    }
    if reference:
        item["reference"] = reference.strip()
    if misconception:
        item["misconception"] = misconception.strip()
    items.append(item)

